CREATE OR REPLACE FUNCTION public.library_manage_note_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_expected record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.version := 1;
    NEW.last_operation_id := NULL;
    NEW.created_at := now();
    NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.version := OLD.version + 1;
    NEW.updated_at := now();
    IF NEW.last_operation_id IS NOT DISTINCT FROM OLD.last_operation_id THEN
      NEW.last_operation_id := NULL;
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.user_book_id IS DISTINCT FROM OLD.user_book_id THEN
      RAISE EXCEPTION 'LIBRARY_NOTES_IDENTITY_IMMUTABLE';
    END IF;
    RETURN NEW;
  END IF;
  RETURN NULL;
END
$function$
